#define COUNT (sizeof(definitions)/sizeof(definitions[0]))

size_t gutc_api_registry_count(void) {return COUNT;}

gutc_status gutc_api_registry_at(size_t index,gutc_json_dom **output) {
  const char *json;
  if(!output)return GUTC_INVALID_ARGUMENT;
  *output=NULL;
  if(index>=COUNT)return GUTC_RANGE_ERROR;
  json=definitions[index].json;
  return gutc_json_dom_parse((const uint8_t*)json,strlen(json),64,10000,
                              output,NULL);
}
gutc_status gutc_api_registry_lookup(const char *id,size_t length,
                                      gutc_json_dom **output,int *found) {
  size_t i;
  if(!output||!found||(!id&&length))return GUTC_INVALID_ARGUMENT;
  *output=NULL;*found=0;
  for(i=0;i<COUNT;i++) {
    size_t n=strlen(definitions[i].id);
    if(n==length && (!n||memcmp(definitions[i].id,id,n)==0)) {
      gutc_status rc=gutc_api_registry_at(i,output);
      if(rc==GUTC_OK)*found=1;
      return rc;
    }
  }
  return GUTC_OK;
}
gutc_status gutc_api_registry_list(gutc_json_dom **output) {
  size_t i,total=2,pos=0;
  char *source;
  gutc_status rc;
  if(!output)return GUTC_INVALID_ARGUMENT;
  *output=NULL;
  for(i=0;i<COUNT;i++) {
    const size_t n=strlen(definitions[i].json);
    if(n>SIZE_MAX-total-1)return GUTC_OVERFLOW;
    total+=n+1;
  }
  if(total>1048576u)return GUTC_RANGE_ERROR;
  source=(char*)malloc(total+1);
  if(!source)return GUTC_NO_MEMORY;
  source[pos++]='[';
  for(i=0;i<COUNT;i++) {
    const size_t n=strlen(definitions[i].json);
    if(i)source[pos++]=',';
    memcpy(source+pos,definitions[i].json,n);
    pos+=n;
  }
  source[pos++]=']';
  source[pos]='\0';
  rc=gutc_json_dom_parse((const uint8_t*)source,pos,128,100000,
                         output,NULL);
  free(source);
  return rc;
}
gutc_status gutc_api_registry_fod_nodes(gutc_json_dom **output) {
  gutc_json_dom *catalog=NULL,*result=NULL;
  gutc_status rc;
  size_t i;
  if(!output)return GUTC_INVALID_ARGUMENT;
  *output=NULL;
  rc=gutc_api_registry_list(&catalog);
  if(rc!=GUTC_OK)return rc;
  result=(gutc_json_dom*)calloc(1,sizeof(*result));
  if(!result){gutc_json_dom_free(catalog);return GUTC_NO_MEMORY;}
  result->kind=GUTC_JSON_ARRAY;
  result->as.array.values=(gutc_json_dom**)calloc(COUNT,sizeof(gutc_json_dom*));
  if(!result->as.array.values) {
    gutc_json_dom_free(result);gutc_json_dom_free(catalog);return GUTC_NO_MEMORY;
  }
  for(i=0;i<COUNT;i++) {
    gutc_json_dom *node=NULL;
    rc=gutc_api_to_fod_node(catalog->as.array.values[i],&node);
    if(rc!=GUTC_OK) {
      gutc_json_dom_free(result);
      gutc_json_dom_free(catalog);
      return rc;
    }
    result->as.array.values[i]=node;
    result->as.array.count++;
  }
  gutc_json_dom_free(catalog);
  *output=result;
  return GUTC_OK;
}
